const i={ui:{fig:"Рис. 1",title:"Шоппер · анатомия",svgLabel:"Изометрический рисунок шоппера и того, как он шьётся, шаг за шагом.",prev:"Предыдущий шаг",dot:(t,e)=>t?`Шаг ${t}: ${e}`:e,start:"Шаги →",next:"Дальше →",overview:"Обзор",stepOf:(t,e)=>`Шаг ${t} из ${e}`,machine:t=>`Машина: ${t.toLowerCase()}`,inThisStep:"В этом шаге",takeApart:"Разобрать",putTogether:"Собрать",replay:"↻ Повторить",parts:"Детали",allSteps:"Пошаговая инструкция",endView:"ВИД С ТОРЦА",cutTitle:"Шоппер с подкладом · размеры кроя",cutAlt:"Схема кроя шоппера с подкладом: верх из хлопковой парусины и подклад из атласа, по 86 × 45 см, с линией сгиба посередине, и две ручки из парусины 100 × 16 см.",cutCaption:"Детали, которые нужно выкроить, с размерами — как в шаге 1."},stitches:{straight:"Прямая строчка"},labels:{cm4:"4 см",cm6:"6 см",cm8:"8 см",cm16:"16 см",cm45:"45 см",cm86:"86 см",cm100:"100 см",fold:"сгиб",outerDuck:"верх · парусина",liningSatin:"подклад · атлас",strapsDuck:"2 ручки · парусина",topstitchEdges:"отстрочить оба края",centreCrease:"середина (сгиб)",stitchFold:"строчка у самого сгиба",bottom12:"дно 12 см",liftEnds:"поднять концы на строчках",foldsIn:"дно складывается внутрь",centreInside:"середина — 6 см внутрь",rightSides:"лицом к лицу",seam05:"шов 0,5 см",layers4:"здесь 4 слоя",turnOut:"вывернуть на лицо",openUp:"расправить",base12:"дно 12 см",cornersForm:"уголки получаются сами",opening8:"отверстие 8 см",endsLevel:"концы вровень с верхним краем",turnThrough:"вывернуть через отверстие",stitchClosed:"зашить отверстие",pushLining:"заправить подклад внутрь",topstitch1:"отстрочка 1 см"},steps:[{title:"Готовая сумка",text:"Шоппер с подкладом из трёх частей: верх из хлопковой парусины, атласный подклад и две длинные ручки. Нажмите на сумку, чтобы разобрать её на детали."},{title:"Раскроить детали",text:"Верх: хлопковая парусина, 86 × 45 см. Подклад: атлас, того же размера. Ручки: две полосы парусины, 100 × 16 см.",details:["Выкроите из хлопковой парусины прямоугольник 86 × 45 см для верха и такой же из атласа — для подклада.","Для ручек выкроите из парусины две полосы 100 × 16 см.","На деталях верха и подклада наметьте посередине поперечную линию сгиба — в 43 см от каждой короткой стороны. Она станет дном сумки.","Все припуски на швы в этой сумке — 0,5 см."]},{title:"Сшить ручки",text:"Сложите полосу пополам и заутюжьте, разверните, подогните оба края к сгибу и сложите снова: получится ручка шириной 4 см в четыре слоя. Отстрочите оба края.",details:["Сложите полосу пополам вдоль, изнанкой к изнанке, и заутюжьте сгиб.","Разверните. Подогните оба длинных края к середине, чтобы они сошлись на сгибе, и снова заутюжьте.","Сложите пополам по первому сгибу. Теперь ручка шириной 4 см и толщиной в четыре слоя, а все срезы спрятаны внутри.","Отстрочите оба длинных края прямой строчкой, у самого края. Сделайте так две ручки."]},{title:"Сформировать дно",text:"Заутюжьте сгиб посередине и разверните. Отмерьте по 6 см в обе стороны, сложите по каждой линии и прострочите у самого сгиба: две прострочённые складки — дно 12 см.",details:["Сложите деталь верха пополам поперёк и заутюжьте сгиб. Снова разверните.","Отмерьте от сгиба по 6 см к каждому концу и проведите линии по всей ширине детали.","Сложите по первой линии лицом к лицу и прострочите у самого сгиба. Разверните, затем так же сложите и прострочите по второй линии.","Две прострочённые складки на расстоянии 12 см друг от друга — это края дна, а центральный сгиб — его середина."]},{title:"Заправить дно внутрь",text:"Поднимите оба конца на прострочённых складках и сведите их вместе: дно складывается внутрь, а центральный сгиб уходит на 6 см внутрь. Разложите деталь ровно.",details:["Положите деталь лицевой стороной вверх и поднимите оба конца, чтобы она согнулась по двум прострочённым складкам.","Сведите концы вместе. Дно шириной 12 см складывается внутрь, а центральный сгиб уходит между слоями на 6 см вверх — как дно бумажного пакета.","Разложите ровно, лицом к лицу. Теперь прострочённые складки — нижний край, а сложенная деталь на 6 см короче, чем если бы её просто сложили пополам."]},{title:"Стачать бока",text:"Не расправляя дно, стачайте оба бока швом 0,5 см — через все слои, внизу их четыре.",details:["Закрепите бока зажимами, чтобы заправленное дно не сдвинулось.","Стачайте оба боковых шва в 0,5 см от края, до самого низа. Внизу шов проходит через четыре слоя: перед, две половинки заправленного дна и спинку. Верх оставьте открытым."]},{title:"Вывернуть",text:"Выверните верх на лицевую сторону и расправьте: дно раскрывается в основание шириной 12 см, а уголки получаются сами.",details:["Выверните верх на лицевую сторону через верхний край.","Расправьте сумку и вытолкните дно наружу. Заправленное дно раскрывается в плоское основание шириной 12 см, а там, где его захватили боковые швы, сами собой получаются аккуратные уголки — отдельно прострачивать их не нужно."]},{title:"Сшить подклад",text:"Сшейте атласный подклад так же, но в одном боковом шве оставьте отверстие 8 см — через него вы потом вывернете сумку.",details:["Сшейте подклад точно так же, как верх: заутюжьте сгиб посередине, прострочите две складки в 6 см от него, заправьте дно внутрь.","Стачайте оба боковых шва в 0,5 см от края, но на одном боку оставьте отверстие 8 см — внизу, сразу над заправленным дном. Через него вы вывернете сумку.","Подклад не выворачивайте — пусть остаётся изнанкой наружу."]},{title:"Соединить верх и подклад",text:"Приколите ручки к верху сумки в 6 см от середины. Вложите верх в подклад, вывернутый изнанкой наружу, и прострочите по верхнему краю.",details:["Выверните верх на лицевую сторону.","Приколите ручку к верхнему краю переда: концы вровень со срезом, в 6 см от середины, а петля свисает вниз по сумке. Так же — на спинке.","Вложите верх вместе с ручками в подклад, вывернутый изнанкой наружу, чтобы они оказались лицом к лицу. Совместите боковые швы и верхние края.","Прострочите по всему верхнему краю в 0,5 см от края."]},{title:"Вывернуть и отстрочить",text:"Выверните сумку через отверстие и зашейте его. Заправьте подклад внутрь и отстрочите верх в 1 см от края.",details:["Через отверстие в подкладе выверните всю сумку на лицевую сторону.","Подверните срезы отверстия внутрь и зашейте его у самого края.","Заправьте подклад внутрь сумки и заутюжьте верхний край.","Отстрочите сумку по верху в 1 см от края. Ваш шоппер готов!"]}],legend:[{title:"Верх",text:"хлопковая парусина · крой 86 × 45 см, сгиб по дну"},{title:"Подклад",text:"атлас · крой 86 × 45 см, как у верха"},{title:"Ручки (2 шт.)",text:"крой 100 × 16 см · сложены в четыре слоя до 4 см"},{title:"Дно",text:"две складки, прострочённые в 6 см по обе стороны от центрального сгиба, заправляются внутрь, прежде чем стачиваются боковые швы → основание 12 см, уголки получаются сами"},{title:"Отстрочка",text:"в 1 см от верхнего края · все швы 0,5 см"}]};export{i as default};
